solutionCode:
#[derive(Debug, PartialEq)]
pub enum Prato {
    Cheio,
    Vazio,
}

pub fn o_peso_do(prato: Prato) -> i32 {
    match prato {
        Prato::Cheio => 2,
        Prato::Vazio => -2,
    }
}

testsCode:
use desafio::o_peso_do;
use desafio::Prato;

#[test]
fn testa_o_peso_do_prato_cheio() {
    assert_eq!(o_peso_do(Prato::Cheio), 2);
}

#[test]
fn testa_o_peso_do_prato_vazio() {
    assert_eq!(o_peso_do(Prato::Vazio), -2);
}
